using System.Threading.Tasks;
using ScriptCore;

// Terrain play-mode tests (issue board #16): the procedural terrain generated by
// Tools/GenerateTerrain.py (seed 7, hills, 2x2 tiles of 64 quads at 2 m) is loaded by the engine,
// and its physics collision is queried where the heights are known exactly. At lattice points the
// collision mesh passes through the Float32 page samples, so the expected values below are the
// generator's own numbers (Tools/Tests/test_generate_terrain.py keeps the generator honest).
public static class TerrainTests
{
    private const string Scene = "Assets/Scenes/Tests/TerrainProceduralTest.lvl";

    // World X, Z (terrain at the origin, 2 m spacing) and the page height there; none under a box.
    private static readonly (float X, float Z, float Height)[] LatticePoints =
    {
        (4f, -6f, -2.37905f),   // (0, 0) itself sits under Terrain Box 2
        (20f, -14f, -2.07599f),
        (-60f, 50f, 1.73142f),
        (100f, 120f, 2.73438f),
        (126f, 126f, 2.72445f),
    };

    private static Entity Terrain() => World.Find("Terrain");

    private static float GroundHeightAt(float x, float z, Entity expected)
    {
        bool hit = Physics.Raycast(new Vector3(x, 100f, z), new Vector3(0f, -1f, 0f), 200f, out RaycastHit info);
        GameAssert.True(hit, $"a ray down at ({x}, {z}) hits something");
        GameAssert.Equal(expected, info.Entity, $"the hit at ({x}, {z}) is the terrain");
        return info.Point.y;
    }

    [GameTest(Scene)]
    public static Task Terrain_is_one_reflected_entity()
    {
        Entity terrain = Terrain();
        GameAssert.True(terrain.IsAlive, "the Terrain entity exists");
        GameAssert.Equal(1, Query.WithComponent("Terrain").Length, "exactly one Terrain component");
        GameAssert.Equal("Assets/Terrain/Procedural.terrain", terrain.GetField("Terrain", "Asset", ""), "asset reference");
        GameAssert.True(terrain.GetField("Terrain", "Collision", false), "collision is on");
        GameAssert.Equal(0, terrain.Children.Length, "patches are not scene children");
        return Task.CompletedTask;
    }

    [GameTest(Scene)]
    public static Task Collision_matches_the_generated_heights_at_lattice_points()
    {
        Entity terrain = Terrain();
        foreach (var (x, z, height) in LatticePoints)
        {
            GameAssert.Near(height, GroundHeightAt(x, z, terrain), 0.02f, $"height at ({x}, {z})");
        }
        return Task.CompletedTask;
    }

    [GameTest(Scene)]
    public static Task Collision_interpolates_inside_a_quad()
    {
        // Inside the quad whose corners are the lattice points (0,0) (1,0) (0,1) (1,1): the engine
        // splits it into the triangles (a, c, b) / (b, c, d), so this point lies on the first one.
        GameAssert.Near(-1.96554f, GroundHeightAt(0.5f, 1.0f, Terrain()), 0.02f, "height inside the quad");
        return Task.CompletedTask;
    }

    [GameTest(Scene)]
    public static async Task Boxes_come_to_rest_on_the_surface()
    {
        Entity box = World.Find("Terrain Box 2");
        GameAssert.True(box.IsAlive, "Terrain Box 2 exists");
        // It starts 1 m above the generator's height (-2.0 at x = 0) and settles half its size above it.
        await GameAssert.Eventually(() => System.MathF.Abs(box.Transform.Position.y - -1.5f) < 0.8f, 10f, "the box settles on the terrain");
    }
}
